  "Accepted quotations out of all quotations sent. Higher means more offers turn into sales.": "Devis acceptés sur l'ensemble des devis envoyés. Plus il est élevé, plus les offres se transforment en ventes.",
  "Accepted quotations out of those sent in the period that have been decided: accepted, refused, or past their end date with no answer.": "Devis acceptés parmi ceux envoyés sur la période et tranchés : acceptés, refusés, ou expirés sans réponse.",
  "Accepted quotations turned into work to deliver: what is still to make, what is late against the date promised to the client, and what was delivered but not invoiced. Press a number to show only those.": "Les devis acceptés transformés en travail à livrer : ce qui reste à fabriquer, ce qui est en retard sur la date promise au client, et ce qui a été livré mais pas facturé. Appuyez sur un chiffre pour n'afficher que ceux-là.",
  "accepted this year": "acceptées cette année",
  "accepted, not yet invoiced": "acceptés, pas encore facturés",
