  "active suppliers": "fournisseurs actifs",
  "Active suppliers by where they are with us. Press one to show only them.": "Les fournisseurs actifs selon leur étape avec nous. Appuyez sur une étape pour n'afficher qu'eux.",
  "active users": "utilisateurs actifs",
