  "Add a line": "Ajouter une ligne",
  "Add a new client called Riverside Lodge, phone 020 000 0000.": "Ajoute un nouveau client appelé Riverside Lodge, téléphone 020 000 0000.",
  "Add a person: type a name or ID": "Ajouter une personne : saisissez un nom ou un matricule",
  "Add a photo": "Ajouter une photo",
