  "Add a second lock to your account": "Ajoutez un second verrou à votre compte",
  "Add a sub-meter to any unit set to \"metered\" utilities, then record its readings each period to bill consumption.": "Ajoutez un sous-compteur à tout logement dont les charges sont en mode « au compteur », puis relevez-le à chaque période pour facturer la consommation.",
  "Add a unit here": "Ajouter un logement ici",
