  "An accepted quotation turned into work to deliver: the same lines and total, with the date promised to the client.": "Un devis accepté transformé en travail à livrer : les mêmes lignes et le même total, avec la date promise au client.",
  "An active client with nothing quoted, invoiced or paid for four months.": "Un client actif sans devis, facture ni paiement depuis quatre mois.",
  "An AI assistant that knows the business": "Un assistant IA qui connaît l'entreprise",
  "an hour": "une heure",
  "An invoice is past its due date with money still owed.": "Une facture a dépassé son échéance et il reste un montant dû.",
  "An invoice was made from it. Its status then stays accepted unless that invoice is voided.": "Une facture a été établie à partir de lui. Son statut reste alors accepté, sauf si cette facture est annulée.",
  "An invoice was made from the order. While that invoice stands (not voided), the order can't be cancelled.": "Une facture a été faite à partir de la commande. Tant que cette facture existe (non annulée), la commande ne peut pas être annulée.",
  "An offer is costed as a draft, sent to the prospect, and once accepted becomes a booking. Press a step to show only those.": "Une offre est chiffrée en brouillon, envoyée au prospect, et une fois acceptée devient une réservation. Appuyez sur une étape pour n'afficher que celles-là.",
  "An optional record of the total days agreed with a person, checked against how it is split across the types. It does not limit any request.": "Un enregistrement facultatif du total de jours convenu avec une personne, comparé à sa répartition entre les types. Il ne limite aucune demande.",
  "An order cancelled after it was rung up. A few are normal; many are worth a look.": "Une commande annulée après avoir été saisie. Quelques-unes, c'est normal ; beaucoup, cela mérite un examen.",
  "An order copies the lines and total of an accepted quotation. Only accepted quotations with no order or invoice yet are listed.": "Une commande reprend les lignes et le total d'un devis accepté. Seuls les devis acceptés sans commande ni facture sont listés.",
  "An order taken by phone, WhatsApp or Bolt. Ring it up on Square as usual; the OS links the two by the day and the dishes.": "Une commande prise par téléphone, WhatsApp ou Bolt. Passez-la sur Square comme d’habitude ; l’OS relie les deux par le jour et les plats.",
