  "Announcements": "Annonces",
  "announcements from the last 30 days": "annonces des 30 derniers jours",
  "Annual, compassionate and sick leave all come out of this total. The year's company holidays are part of it, so they are taken off on 1 January; a holiday added or removed during the year changes it at once. Taking more than is left is allowed: the extra days are owed to the company, and HR settles them.": "Les congés annuels, pour événements familiaux et maladie sont tous pris sur ce total. Les jours fériés de l'entreprise de l'année en font partie : ils sont retirés le 1er janvier, et un jour férié ajouté ou retiré en cours d'année le modifie aussitôt. Prendre plus que le reste est possible : les jours en trop sont dus à l'entreprise, et les RH les règlent.",
  "Annual, compassionate and sick leave all come out of this total. The year's company holidays are taken off on 1 January, and the balance follows the holiday list as it changes. More than is left can be taken: the extra days are owed and settled by HR.": "Les congés annuels, pour événements familiaux et maladie sont tous pris sur ce total. Les jours fériés de l'année sont retirés le 1er janvier, et le solde suit la liste des jours fériés quand elle change. On peut prendre plus que le reste : les jours en trop sont dus et réglés par les RH.",
  "another company": "une autre entreprise",
  "Another profile has the same phone, email or name. Data health shows both side by side to merge or tell apart.": "Une autre fiche a le même téléphone, e-mail ou nom. La qualité des données les montre côte à côte pour les fusionner ou les distinguer.",
  "Answer": "Répondre",
  "Answer the {n} new leads still waiting before Monday.": "Répondez avant lundi aux {n} nouvelles pistes qui attendent encore.",
