  "Approved · to pay out": "Approuvé · à rembourser",
  "Approved and paid claims over the last 90 days, by category. Press one to show those claims.": "Demandes approuvées et payées des 90 derniers jours, par catégorie. Appuyez sur une catégorie pour afficher ces demandes.",
  "Approved and paid expense claims dated in the period, plus payroll cost: gross pay, the employer's SSNIT and any PAYE the company pays, for runs approved or paid with a pay date in the period.": "Les notes de frais approuvées et payées datées de la période, plus le coût de la paie : brut, SSNIT employeur et PAYE pris en charge par l'entreprise, pour les paies approuvées ou payées dont la date de paiement tombe dans la période.",
  "Approved and paid runs over the last six months, by the month their period ends. Deductions are PAYE plus SSNIT from staff and employer.": "Cycles approuvés et payés des six derniers mois, selon le mois de fin de période. Les retenues comprennent la PAYE et la SSNIT salarié et employeur.",
  "Approved by": "Approuvé par",
  "Approved by (name & signature)": "Approuvé par (nom et signature)",
  "Approved by {name}": "Approuvé par {name}",
  "approved claims not paid yet": "notes de frais approuvées pas encore payées",
  "Approved expense claims": "Notes de frais approuvées",
  "Approved expense claims by category, and payroll, over the period.": "Notes de frais approuvées par catégorie, et paie, sur la période.",
  "Approved expense claims by the day they were spent, and payroll: gross pay plus the employer's SSNIT and any PAYE the company pays, for runs approved or paid, by pay date.": "Les notes de frais approuvées, au jour de la dépense, et la paie : salaire brut plus la SSNIT employeur et le PAYE que l'entreprise prend en charge, pour les paies approuvées ou payées, à la date de paiement.",
  "Approved expenses so far this month, by category.": "Dépenses approuvées ce mois-ci, par catégorie.",
  "approved leave": "congé approuvé",
  "approved leave ahead": "congés approuvés à venir",
  "Approved leave in solid colour, requests still waiting for a decision striped.": "Congés approuvés en couleur pleine, demandes en attente de décision en rayures.",
  "approved or on order": "approuvées ou en commande",
  "Approved pay runs": "Cycles de paie approuvés",
