  "As of {date}, every company together.": "Au {date}, toutes les entreprises réunies.",
  "As of {date}.": "Au {date}.",
  "As on the stock sheet": "Comme sur la fiche de stock",
  "as terminated and disables their login. Their history (attendance, leave, work orders, documents) is kept for records — this does not permanently erase them.": "comme ayant quitté l’entreprise et désactive sa connexion. Son historique (présences, congés, ordres de travail, documents) est conservé — cela ne l’efface pas définitivement.",
  "Ask about attendance, stock, sales, approvals…": "Posez une question sur les pointages, le stock, les ventes, les approbations…",
  "Ask about the company in plain words. It answers only from what your role can see, and when you ask it to do something it prepares it — nothing happens until you press Confirm. Press a number to go to it.": "Posez vos questions sur l'entreprise avec des mots simples. Il ne répond qu'à partir de ce que votre rôle peut voir, et quand vous lui demandez de faire quelque chose, il le prépare — rien ne se passe tant que vous n'appuyez pas sur Confirmer. Appuyez sur un chiffre pour y aller.",
  "Ask again for past chats": "Redemander les anciennes discussions",
  "Ask for something to be bought and follow it: approved, ordered, received. You get a notification at each step.": "Demandez un achat et suivez-le : approuvé, commandé, reçu. Vous êtes prévenu à chaque étape.",
  "Ask for the location": "Demander l’adresse",
  "Ask for time off and follow your requests. Days are working days: Sundays and public holidays are not counted.": "Demandez des congés et suivez vos demandes. Les jours sont des jours ouvrés : les dimanches et jours fériés ne comptent pas.",
  "Ask for time off, decide on your team's requests and see who is away, for {scope}. Days are working days: Sundays and public holidays are not counted. Press a number to show only those requests.": "Demandez des congés, décidez des demandes de votre équipe et voyez qui est absent, pour {scope}. Les jours sont des jours ouvrés : les dimanches et jours fériés ne comptent pas. Appuyez sur un chiffre pour n'afficher que ces demandes.",
  "Ask guests how the food was; what they say shows here, grouped.": "Demandez aux clients comment était le repas ; leurs réponses s’affichent ici, regroupées.",
  "Ask if the quotation works for them and answer any questions.": "Demandez si le devis leur convient et répondez à leurs questions.",
  "Ask in your own words, in English, French or Chinese. It looks things up before answering and never changes anything without your Confirm.": "Posez vos questions avec vos mots, en anglais, en français ou en chinois. Il vérifie avant de répondre et ne modifie jamais rien sans votre confirmation.",
  "Ask people to confirm they have read it": "Demander aux personnes de confirmer leur lecture",
  "Ask to buy 20 bags of cement for the workshop.": "Demande l'achat de 20 sacs de ciment pour l'atelier.",
  "Ask to buy something": "Demander un achat",
  "Asked": "Demandé",
  "asked {n} days ago": "demandé il y a {n} jours",
  "asked about {what}": "ont demandé : {what}",
  "Asked about it on {channel} on {date}: “{text}”": "L'a demandé sur {channel} le {date} : « {text} »",
  "Asked for on {date}. They arrive in batches; Data health shows how far they have got.": "Demandés le {date}. Ils arrivent par lots ; la page Qualité des données indique leur progression.",
  "Asked for, not decided yet. The person's manager (or HR) approves or rejects it.": "Demandé, pas encore décidé. Le responsable de la personne (ou les RH) l'approuve ou le refuse.",
  "asked just now": "demandé à l'instant",
  "Asked Meta again for the contacts and past chats.": "Les contacts et les anciennes discussions ont été redemandés à Meta.",
  "asked today": "demandé aujourd'hui",
  "asked yesterday": "demandé hier",
  "asked, not decided": "demandé, pas encore décidé",
  "Asking Meta…": "Question à Meta…",
  "Asking rent": "Loyer demandé",
  "Asking rent, per month": "Loyer demandé, par mois",
  "Asks Meta whether everything a WhatsApp message needs on its way to the OS is in place.": "Demande à Meta si tout ce qu’il faut pour qu’un message WhatsApp arrive dans l’OS est en place.",
  "Asks Meta whether the OS can read the Page’s chats and the Instagram direct messages.": "Demande à Meta si l’OS peut lire les discussions de la Page et les messages privés Instagram.",
  "asks you to say you have read it": "vous demande de confirmer la lecture",
