  "At the counter": "Au comptoir",
  "At the end of a shift the cashier counts the cash. It should match the starting cash plus cash sales plus money paid in, minus money paid out.": "En fin de service, le caissier compte l'argent. Il doit correspondre au fond de caisse, plus les ventes en espèces et les entrées, moins les sorties.",
