  "Bamboo lost while making the batch (offcuts, splits), as a share of the bamboo used. Above {n}% is flagged.": "Bambou perdu pendant la fabrication (chutes, fentes), en part du bambou utilisé. Au-delà de {n} %, c'est signalé.",
