  "Bamboo OS sends the clock-ins and attendance of {company} staff to your system. Times are Ghana time (GMT, the same as UTC). GPS locations, photos, notes and pay are never sent.": "Bamboo OS envoie les pointages et la présence du personnel de {company} à votre système. Les heures sont à l'heure du Ghana (GMT, identique à UTC). Les positions GPS, photos, notes et salaires ne sont jamais envoyés.",
