  "Bamboo received from suppliers and farmers, what is still in the yard, and what the factory made from it. Each production record takes bamboo from a raw batch and adds the product to stock. Press a number to show only those.": "Le bambou reçu des fournisseurs et des agriculteurs, ce qui reste dans la cour et ce que l'usine en a fabriqué. Chaque enregistrement de production prend du bambou d'un lot brut et ajoute le produit au stock. Appuyez sur un chiffre pour n'afficher que ceux-là.",
