  "Comments and messages logged here are tracked in Bamboo OS — a reply you send below is recorded as the reply, but doesn't post back to Facebook/Instagram/TikTok/WhatsApp itself yet (that needs the channel's live API connected first). Until then, send your reply on the actual platform and record it here.": "Les commentaires et messages consignés ici sont suivis dans Bamboo OS — une réponse envoyée ci-dessous est enregistrée comme étant la réponse, mais n'est pas encore republiée sur Facebook/Instagram/TikTok/WhatsApp (cela nécessite d'abord la connexion de l'API du canal). En attendant, envoyez votre réponse sur la plateforme elle-même, puis consignez-la ici.",
  "Comments and messages people sent, so nobody is left without an answer.": "Commentaires et messages reçus, pour que personne ne reste sans réponse.",
