  "Copy the ID and name columns from your sheet (TimeStation, payroll, ID cards) and paste them below, one person per line. Surname first is fine. You will see who each line matches before anything changes.": "Copiez les colonnes identifiant et nom de votre feuille (TimeStation, paie, cartes d'identité) et collez-les ci-dessous, une personne par ligne. Le nom de famille en premier convient. Vous verrez à qui correspond chaque ligne avant toute modification.",
  "Copy the message": "Copier le message",
  "Copy the name (or employee ID) and start date columns from your HR or payroll sheet and paste them below, one person per line. Dates like 11/03/2019, 2019-03-11 or 11 Mar 2019 all work. You will see who each line matches and what changes before anything is saved.": "Copiez les colonnes du nom (ou du matricule) et de la date d’entrée depuis votre fichier RH ou de paie, puis collez-les ci-dessous, une personne par ligne. Les dates comme 11/03/2019, 2019-03-11 ou 11 mars 2019 fonctionnent toutes. Vous verrez à qui correspond chaque ligne et ce qui change avant tout enregistrement.",
