  "e.g. sliding door, bamboo bed, 20 poles": "ex. porte coulissante, lit en bambou, 20 perches",
  "e.g. Star Bar schedule tracker": "ex. Suivi des plannings Star Bar",
  "e.g. the MoMo transaction ID": "ex. l'identifiant de la transaction MoMo",
  "e.g. The tenant left in 2025 and cannot be reached": "ex. Le locataire est parti en 2025 et est injoignable",
  "e.g. Toyota Hilux GT-1234-20": "ex. Toyota Hilux GT-1234-20",
  "e.g. Weaving Line": "ex. Ligne de tissage",
  "e.g. Weekly production review": "ex. Revue hebdomadaire de production",
  "Each card adds up what needs doing, up to 100: a message waiting for a reply (45 and more the longer it waits), a new lead nobody has called (30+), a follow-up date passed (25+) or today (22), an invoice overdue (25+), a won deal not paid (30), a quotation running out (25) or not answered (20+), a customer gone quiet for 45 days (15+), agreeing the price (15), stuck in a stage for 14 days (10+), no next step (10), a big deal (up to 20), a VIP (10) or a referral (5).": "Chaque carte additionne ce qui reste à faire, jusqu'à 100 : un message en attente de réponse (45, et plus il attend, plus c'est élevé), une nouvelle piste que personne n'a appelée (30+), une date de relance dépassée (25+) ou aujourd'hui (22), une facture en retard (25+), une affaire gagnée non payée (30), un devis qui expire (25) ou sans réponse (20+), un client silencieux depuis 45 jours (15+), une négociation de prix (15), bloqué à une étape depuis 14 jours (10+), pas de prochaine étape (10), une grosse affaire (jusqu'à 20), un VIP (10) ou une recommandation (5).",
  "Each change is sent as a POST with a JSON body to the address you gave, within about half a minute. Answer with any 2xx status and a short reply such as {\"received\":true} to accept it, only after the records are saved (not a web page: Bamboo OS shows the reply on its log). Anything else, or no answer within 10 seconds, and it is sent again later (30 seconds, then longer, up to every hour) until you accept it; nothing is skipped and the order is kept. Use each event's id to ignore one you already have.": "Chaque modification est envoyée en POST avec un corps JSON à l'adresse que vous avez donnée, en une demi-minute environ. Répondez avec un statut 2xx et une réponse courte comme {\"received\":true} pour l'accepter, seulement après avoir enregistré les données (pas une page web : Bamboo OS affiche la réponse dans son journal). Toute autre réponse, ou aucune réponse sous 10 secondes, et elle est renvoyée plus tard (30 secondes, puis plus longtemps, jusqu'à toutes les heures) jusqu'à ce que vous l'acceptiez ; rien n'est sauté et l'ordre est conservé. Utilisez l'id de chaque événement pour ignorer ceux que vous avez déjà.",
  "Each company keeps its own list for each year, and the number can differ from year to year. A year's holidays come off everyone's yearly total on 1 January; adding or removing one changes the balances at once. A holiday inside someone's leave is not charged again.": "Chaque entreprise tient sa propre liste pour chaque année, et leur nombre peut varier d'une année à l'autre. Les jours fériés d'une année sont retirés du total annuel de chacun le 1er janvier ; en ajouter ou en retirer modifie aussitôt les soldes. Un jour férié pendant un congé n'est pas décompté une seconde fois.",
  "Each company keeps its own list. These aren't subtracted from anyone's entitlement — a holiday that falls inside an approved leave request simply isn't charged against the balance, the same way Sundays aren't.": "Chaque société tient sa propre liste. Ces jours ne sont retranchés du droit à congés de personne — un jour férié tombant à l'intérieur d'une demande de congé approuvée n'est tout simplement pas décompté du solde, au même titre que les dimanches.",
  "Each company with its departments, biggest first.": "Chaque société avec ses services, les plus grands d'abord.",
  "Each day": "Chaque jour",
  "Each delivery is a batch. The bar shows how much has gone into production, been written off, or is left.": "Chaque livraison est un lot. La barre montre ce qui est parti en production, passé en perte ou restant.",
  "Each dot is someone clocking in, at the time they did.": "Chaque point est une personne qui pointe, à l'heure où elle l'a fait.",
  "each expires {m} minutes after it was prepared": "chacune expire {m} minutes après avoir été préparée",
  "Each idea comes from what customers asked. The numbers say why.": "Chaque idée vient de ce que les clients ont demandé. Les chiffres expliquent pourquoi.",
  "Each keeps what its lines say": "Chacune garde ce qu'indiquent ses lignes",
  "Each number is compared with the 30 days just before.": "Chaque chiffre est comparé aux 30 jours juste avant.",
  "Each one": "Un par un",
  "Each person's days a year — their own if they have one, else their company's — less that year's company holidays, taken off on 1 January. {types} all come out of it. Taking more than is left is allowed; the extra is owed and settled by HR.": "Les jours par an de chaque personne — les siens s'il en a, sinon ceux de son entreprise — moins les jours fériés de l'année, retirés le 1er janvier. {types} en sont tous déduits. Prendre plus que le reste est possible ; l'excédent est dû et réglé par les RH.",
  "Each post drew {n} likes, comments and shares on average.": "Chaque publication a obtenu en moyenne {n} mentions J'aime, commentaires et partages.",
  "Each rep sees their customers on their follow-ups with the message, and contacts them one by one — personal messages, not a mass send.": "Chaque commercial voit ses clients dans ses relances avec le message, et les contacte un par un — des messages personnels, pas un envoi de masse.",
  "Each reply is signed with the name of the person who wrote it, followed by this name.": "Chaque réponse porte le nom de la personne qui l’a écrite, suivi de ce nom.",
  "Each sale becomes a won lead. It is linked to its OS invoice when exactly one invoice matches the customer, the amount and the date; the others wait for someone to link them.": "Chaque vente devient un prospect gagné. Elle est liée à sa facture de l'OS quand une seule facture correspond au client, au montant et à la date ; les autres attendent que quelqu'un les lie.",
  "Each sale is an OS invoice linked to a won lead. Press the lead to open it.": "Chaque vente est une facture de l'OS liée à un prospect gagné. Appuyez sur le prospect pour l'ouvrir.",
  "Each sales rep side by side {period}. A sale counts for its sales order's rep, else the customer's. Press a name to see their customers.": "Chaque commercial côte à côte {period}. Une vente compte pour le commercial de sa commande, sinon pour celui du client. Appuyez sur un nom pour voir ses clients.",
  "Each shift on the till: the cash that should be in the drawer against what was counted when it closed.": "Chaque service en caisse : l'argent qui devrait être dans la caisse face à ce qui a été compté à la fermeture.",
  "Each shift runs from its start hour to the next shift's start; the last one runs past midnight.": "Chaque service va de son heure de début au début du service suivant ; le dernier dépasse minuit.",
  "Each tenant gets one invoice with all their meters on it. Tick their service charge (CAM) or other recurring charges to put them on the same invoice. Every line shows its working.": "Chaque locataire reçoit une seule facture avec tous ses compteurs. Cochez ses charges de service (CAM) ou autres frais récurrents pour les ajouter à la même facture. Chaque ligne montre son calcul.",
  "Each total is compared with the same number of days just before the dates you picked.": "Chaque total est comparé au même nombre de jours juste avant les dates choisies.",
  "each unit's share %": "part de chaque logement en %",
  "Each unit's share %": "Part de chaque logement en %",
