  "Email inbox": "Boîte de réception e-mail",
  "Email is connected": "L'e-mail est connecté",
  "Email isn't set up yet. An administrator connects the company mailbox in Company settings → Email, then this can be sent.": "L'e-mail n'est pas encore configuré. Un administrateur connecte la boîte mail de l'entreprise dans Paramètres de l'entreprise → E-mail, puis l'envoi sera possible.",
  "Email isn't set up, so two-step sign-in codes can't be sent by email. Add the SMTP settings in Render.": "L'e-mail n'est pas configuré : les codes de connexion en deux étapes ne peuvent pas être envoyés par e-mail. Ajoutez les paramètres SMTP dans Render.",
  "Email me a code": "M'envoyer un code par e-mail",
