  "Email this reminder to {name} at {email} now, with the bill attached?": "Envoyer maintenant ce rappel par e-mail à {name} ({email}), avec la facture jointe ?",
  "Emailed before": "Déjà envoyé par e-mail",
  "Emails brought in": "E-mails importés",
  "Emails from customers, one conversation per email thread, on the customer's profile — a new profile is made for someone new.": "Les e-mails des clients, une conversation par fil d’e-mails, sur la fiche du client — une nouvelle fiche est créée pour une nouvelle personne.",
  "Emails the reminder straight away, with the bill attached as a PDF and a link to view it online. Only for people with an email address on file.": "Envoie le rappel par e-mail immédiatement, avec la facture en PDF et un lien pour la consulter en ligne. Seulement pour les personnes ayant une adresse e-mail enregistrée.",
