  "Enter a date and follower count first.": "Saisissez d'abord une date et un nombre d'abonnés.",
  "Enter a valid year.": "Saisissez une année valide.",
  "Enter email to import…": "Saisissez l'e-mail à importer…",
  "Enter the 6-digit code from your authenticator app, or the one we just sent you.": "Saisissez le code à 6 chiffres de votre application d'authentification, ou celui que nous venons de vous envoyer.",
  "Enter the 6-digit code from your authenticator app.": "Saisissez le code à 6 chiffres de votre application d'authentification.",
  "Enter the 6-digit code we emailed to {email}.": "Saisissez le code à 6 chiffres envoyé par e-mail à {email}.",
  "Enter the 6-digit code we texted to {phone}.": "Saisissez le code à 6 chiffres envoyé par SMS au {phone}.",
  "Enter the code": "Saisissez le code",
  "Enter the email you sign in with, then choose where we send a 6-digit code to choose a new password.": "Saisissez l'e-mail avec lequel vous vous connectez, puis choisissez où nous envoyons un code à 6 chiffres pour choisir un nouveau mot de passe.",
  "Enter the temporary password you were given, then choose a new one.": "Saisissez le mot de passe temporaire reçu, puis choisissez-en un nouveau.",
  "Enter your 4-digit PIN, the same one you clock in with. The till then stays open for your shift on this device.": "Saisissez votre code à 4 chiffres, le même que pour pointer. La caisse reste ensuite ouverte pour votre service sur cet appareil.",
  "Enter your password to make new backup codes (the old ones stop working):": "Saisissez votre mot de passe pour créer de nouveaux codes de secours (les anciens ne fonctionneront plus) :",
  "Enter your password to remove the authenticator app:": "Saisissez votre mot de passe pour retirer l'application d'authentification :",
