  "Five customers made {pct}% of sales {period}. Losing one of them would be felt; winning new ones spreads the risk.": "Cinq clients ont fait {pct} % des ventes {period}. En perdre un se sentirait ; en gagner de nouveaux répartit le risque.",
  "Fix a line, its working, the quantity or the rate, add or remove a line, or move the due date. The invoice keeps its number; what is owed follows the new total. If it was already sent, send it again after saving.": "Corrigez une ligne, son calcul, la quantité ou le tarif, ajoutez ou retirez une ligne, ou décalez l'échéance. La facture garde son numéro ; le montant dû suit le nouveau total. Si elle a déjà été envoyée, renvoyez-la après l'enregistrement.",
