  "Grouped by the exact tax rate on each invoice line, or set on the whole invoice. Where two configured taxes share a rate (NHIL and GETFund both default to 2.5%), the label shows both rather than guessing which applies.": "Regroupé par taux exact sur chaque ligne de facture, ou appliqué à la facture entière. Quand deux taxes configurées ont le même taux (NHIL et GETFund valent par défaut 2,5 %), le libellé les indique toutes deux plutôt que de deviner.",
