  "Guests appear here from three places: the order sheet customer service has kept (import it once), new phone, WhatsApp and Bolt orders logged here, and sales rung up on Square with a customer.": "Les clients apparaissent ici depuis trois sources : le tableau tenu par le service client (à importer une fois), les nouvelles commandes par téléphone, WhatsApp et Bolt enregistrées ici, et les ventes passées sur Square avec un client.",
