  "Guests with three orders or more who have not ordered for twice as long as usual (at least 30 days). A message with what they like often brings them back.": "Clients ayant au moins trois commandes et qui n’ont pas commandé depuis deux fois plus longtemps que d’habitude (au moins 30 jours). Un message avec ce qu’ils aiment les fait souvent revenir.",
