  "Half of the customers' messages in the last 7 days were answered faster than this, half slower — counted from their first message until our next one, nights included.": "La moitié des messages des clients des 7 derniers jours ont eu une réponse plus rapide, l’autre moitié plus lente — compté de leur premier message jusqu’à notre réponse suivante, nuits comprises.",
