  "How likely the customer wants it, out of 100: asked about it recently scores most, then quoted but didn't buy, has a lead for it, bought it before, buys the same kind of thing.": "Probabilité que le client le veuille, sur 100 : l'avoir demandé récemment compte le plus, puis avoir reçu un devis sans acheter, avoir un prospect pour ce produit, l'avoir déjà acheté, acheter le même type de produit.",
