  "Items, their variations and their Square pictures, updated in place. Photos, stock and links added here are kept; an item gone from Square is made inactive.": "Les articles, leurs variantes et leurs images Square, mis à jour sur place. Les photos, le stock et les liens ajoutés ici sont conservés ; un article retiré de Square devient inactif.",
  "Its invoice asks for {invoiced}, but the booking's rent is {rent}: the booking was changed before invoices followed changes. Press Edit, then Save, to bring the invoice up to date.": "Sa facture demande {invoiced}, mais le loyer de la réservation est de {rent} : la réservation a été modifiée avant que les factures suivent les modifications. Cliquez sur Modifier, puis Enregistrer, pour mettre la facture à jour.",
  "Its owner is told, and it reopens by itself if one of them is opened again or a new one is added. Leave this off to close the project yourself.": "Son responsable est prévenu, et il se rouvre tout seul si l’un d’eux est rouvert ou si un nouveau est ajouté. Laissez décoché pour clôturer le projet vous-même.",
