  "Keep as written": "Garder tel qu’écrit",
  "Keep in touch": "Garder le contact",
  "Keep it": "Le garder",
  "Keep open": "Garder ouverte",
  "Keep the key file private — never send it in a chat or email. The OS can only read what is shared with that email, and can't change anything in Drive.": "Gardez le fichier de clé privé — ne l'envoyez jamais dans une discussion ou un e-mail. L'OS ne peut lire que ce qui est partagé avec cet e-mail, et ne peut rien modifier dans Drive.",
  "Keep the other one instead": "Garder plutôt l'autre",
  "Keep the signing secret on your server only. The read key too, unless your web page reads the feed itself: then anyone who looks at the page's code can see it and read the same names and clock times, so share the page only with people who may see them. If either is ever seen by someone it shouldn't be, ask for a new one: the old one stops working at once.": "Gardez le secret de signature uniquement sur votre serveur. La clé de lecture aussi, sauf si votre page web lit elle-même le flux : alors toute personne qui regarde le code de la page peut la voir et lire les mêmes noms et heures de pointage, donc ne partagez la page qu'avec des personnes autorisées à les voir. Si l'un d'eux est vu par quelqu'un qui ne devrait pas, demandez-en un nouveau : l'ancien cesse aussitôt de fonctionner.",
  "Keep this order open": "Garder cette commande ouverte",
  "Keep this order open to add to and pay later": "Garder cette commande ouverte pour y ajouter et payer plus tard",
  "Keeping the secret and key safe": "Garder le secret et la clé en sécurité",
  "Keeps both. The OS won't suggest this pair again.": "Conserve les deux. L'OS ne suggérera plus cette paire.",
  "Keeps the customer list clean and covered: one profile per customer, a sales rep for everyone who needs one, and every channel flowing in. The OS checks every hour and tells the sales managers each morning when customers have no rep.": "Garde la liste des clients propre et couverte : une fiche par client, un commercial pour chacun de ceux qui en ont besoin, et tous les canaux qui alimentent le CRM. L'OS vérifie toutes les heures et prévient chaque matin les responsables commerciaux lorsque des clients n'ont pas de commercial.",
  "Kept": "Conservé",
  "Kept apart. The OS won't suggest this pair again.": "Gardées séparées. L'OS ne suggérera plus cette paire.",
  "kept as written": "gardé tel qu’écrit",
  "Kept at": "Rangé à",
  "Kept at the top of the noticeboard until unpinned.": "Reste en haut du tableau jusqu'à ce qu'elle soit désépinglée.",
  "Kept in the audit log with each invoice.": "Conservé dans le journal d’audit avec chaque facture.",
  "Kept in the audit log with your name.": "Conservé dans le journal d’audit à votre nom.",
