  "Leads & prospects to follow up": "Pistes et prospects à relancer",
  "Leads are new enquiries (new, contacted, follow-up). Prospects are real jobs (qualified, quote sent, negotiation, or won and waiting for the money). Customers have paid, and you look after their account.": "Les pistes sont les nouvelles demandes (nouvelle, contactée, relance). Les prospects sont de vrais projets (qualifié, devis envoyé, négociation, ou gagné en attente du paiement). Les clients ont payé, et vous suivez leur compte.",
  "Leads being worked on for real: qualified, quoted, or agreeing terms. Won ones wait here until they pay; with the first payment they become customers by themselves.": "Les pistes travaillées pour de vrai : qualifiées, avec devis, ou en négociation. Celles gagnées attendent ici leur paiement ; au premier paiement, elles deviennent clientes d’elles-mêmes.",
  "Leads by stage. Next moves one on; Make a prospect when it is a real job.": "Les pistes par étape. Suivant fait avancer ; En faire un prospect quand c’est un vrai projet.",
  "Leads received {period} by how they found us, and how many were won.": "Prospects reçus ({period}) selon la façon dont ils nous ont trouvés, et combien ont été gagnés.",
  "Leads, follow-ups and site visits: the work that turns enquiries into the sales above.": "Pistes, relances et visites de site : le travail qui transforme les demandes en ventes ci-dessus.",
  "Least stock first": "Stock le plus bas d'abord",
