  "Message deleted.": "Message supprimé.",
  "Message only people who wrote to you or agreed to hear from you, and send fewer messages they didn't ask for. The limit goes back up when the quality improves.": "N'écrivez qu'aux personnes qui vous ont écrit ou qui ont accepté d'être contactées, et envoyez moins de messages non sollicités. La limite remonte quand la qualité s'améliore.",
  "Message template “{name}” ({lang}) was approved.": "Le modèle de message « {name} » ({lang}) a été approuvé.",
  "Message template “{name}” ({lang}) was rejected: {reason}.": "Le modèle de message « {name} » ({lang}) a été refusé : {reason}.",
