  "Off by {amount} — check the typed-in figures below (Cash & bank is usually the one to correct).": "Écart de {amount} — vérifiez les montants saisis ci-dessous (la trésorerie est généralement celle à corriger).",
  "Off by {amount} against what the invoices recorded.": "Écart de {amount} par rapport à ce que les factures ont enregistré.",
