  "Open work orders each project manager has, how many are late, and what they finished in the last 30 days. Press one to show only theirs.": "Les ordres de travail ouverts de chaque chef de projet, combien sont en retard, et ce qu’il a terminé ces 30 derniers jours. Appuyez sur un nom pour n’afficher que les siens.",
