  "Orders customer service takes by phone, WhatsApp or Bolt, newest first, with what the guest said. Each is linked to its sale on the till when the OS finds it.": "Les commandes prises par le service client par téléphone, WhatsApp ou Bolt, les plus récentes en premier, avec l’avis du client. Chacune est reliée à sa vente en caisse quand l’OS la trouve.",
