  "Send one company's clock-ins and attendance to another system, like a restaurant's own staff schedule tracker. It is sent to their address as it happens, or their system reads it with a key — or both. GPS locations, photos, notes and pay are never sent.": "Envoyez les pointages et la présence d'une entreprise vers un autre système, comme le suivi des plannings du personnel d'un restaurant. C'est envoyé à leur adresse en temps réel, ou leur système le lit avec une clé — ou les deux. Les positions GPS, photos, notes et salaires ne sont jamais envoyés.",
