  "Tabs read: {tabs}. The dashboard, summary and lists are worked out by the OS, so they aren't imported.": "Onglets lus : {tabs}. Le tableau de bord, le résumé et les listes sont calculés par l'OS, ils ne sont donc pas importés.",
  "Tag": "Étiquette",
  "Take back": "Reprendre",
  "Take back {tag}": "Reprendre {tag}",
  "Take back into storage": "Reprendre en réserve",
  "Take it away from everyone first": "Retirez-le d'abord à tout le monde",
  "Take it back": "Le récupérer",
  "Take off the invoice": "Déduire de la facture",
  "Take out of their project": "Retirer de leur projet",
  "Take payment": "Encaisser",
  "Take payments against what tenants owe, raise one-off charges, and turn meter readings and shared building bills into utility invoices. Rent itself is invoiced when a booking is made. Press a number to go to it.": "Encaissez les paiements des locataires, facturez des frais ponctuels, et transformez relevés de compteur et factures communes en factures de charges. Le loyer est facturé à la réservation. Appuyez sur un chiffre pour y aller.",
  "Take some of the invoice back, and refund what the customer then paid over what they owe.": "Annulez une partie de la facture et remboursez ce que le client a alors payé en trop.",
  "Take this customer": "Prendre ce client",
