  "Takes stock from": "Prend le stock de",
  "takes stock from {name} ({n} in stock)": "prend le stock de {name} ({n} en stock)",
  "Takes the payment off: the amount goes back on the invoice and its receipt is removed.": "Retire le paiement : le montant revient sur la facture et son reçu est supprimé.",
  "Tap ⋮ (or the name on iPhone) → More → Export chat → Without media.": "Appuyez sur ⋮ (ou sur le nom sur iPhone) → Plus → Exporter la discussion → Sans les médias.",
  "Tap a dish to start.": "Touchez un plat pour commencer.",
  "Tap here and choose Allow. Staff who clock in by face can’t use this device until someone does.": "Touchez ici et choisissez Autoriser. Le personnel qui pointe par reconnaissance faciale ne pourra pas utiliser cet appareil tant que ce ne sera pas fait.",
  "Tap to hear the call": "Touchez pour entendre l'appel",
  "Tap your 4-digit PIN. The same PIN clocks you in when you arrive and out when you leave.": "Saisissez votre code à 4 chiffres. Le même code pointe votre arrivée et votre départ.",
  "Tap your PIN": "Saisissez votre code",
