  "who it is for": "le destinataire",
  "Who it is for": "Pour qui",
  "Who it is for (optional)": "Pour qui (facultatif)",
  "Who it is for: all staff, one company's staff or one department. Only they see it and get a notification.": "À qui elle s'adresse : tout le personnel, le personnel d'une société ou un service. Seules ces personnes la voient et reçoivent une notification.",
  "Who Meta lets write in (App Review)": "Qui Meta laisse écrire (App Review)",
  "Who moves in over the next 30 days and which bookings end over the next 90. Hover a marker for the tenant.": "Qui emménage dans les 30 prochains jours et quelles réservations se terminent dans les 90 prochains. Survolez un repère pour voir le locataire.",
  "Who needs the team today": "Qui a besoin de l'équipe aujourd'hui",
  "Who orders, how often, how they order and what they think of the food. Orders come from the till (Square) and from the order log customer service keeps for phone, WhatsApp and Bolt orders. Press a number to go to it.": "Qui commande, à quelle fréquence, comment, et ce qu’ils pensent des plats. Les commandes viennent de la caisse (Square) et du registre que tient le service client pour les commandes par téléphone, WhatsApp et Bolt. Appuyez sur un chiffre pour y aller.",
  "Who owes the most": "Qui doit le plus",
  "Who owes us": "Qui nous doit",
  "Who owns the open projects, and how many are behind, late or ready to close. Press one to show only theirs.": "Qui est responsable des projets ouverts, et combien sont à la traîne, en retard ou prêts à clôturer. Appuyez sur un nom pour n’afficher que les siens.",
  "Who pays PAYE": "Qui paie le PAYE",
