  "Yearly leave: what each person has left of their total less the {year} company holidays, and what they owe. The other columns are leave types with their own days. Press Adjust to change someone's total.": "Congés annuels : ce qu'il reste à chaque personne de son total moins les jours fériés {year}, et ce qu'elle doit. Les autres colonnes sont les types de congé avec leurs propres jours. Appuyez sur Ajuster pour modifier le total d'une personne.",
