  "You": "Vous",
  "You already have a face on file — continuing replaces it.": "Un visage est déjà enregistré pour vous — continuer le remplacera.",
  "You are almost out of {types}.": "Vous avez presque épuisé vos {types}.",
  "You are already in a call. Leave it first.": "Vous êtes déjà en appel. Quittez-le d'abord.",
  "You are number {rank} of {of}.": "Vous êtes numéro {rank} sur {of}.",
  "You are sharing your screen": "Vous partagez votre écran",
  "You are signed in as the record that would be removed. Press ⇄ to keep the one you sign in with.": "Vous êtes connecté avec la fiche qui serait supprimée. Appuyez sur ⇄ pour garder celle avec laquelle vous vous connectez.",
  "you are told when it arrives": "vous êtes prévenu à l'arrivée",
  "you are up to date": "vous êtes à jour",
  "You are up to date: nothing new since you last looked.": "Vous êtes à jour : rien de nouveau depuis votre dernière visite.",
  "You can also upload the monthly summary tab (e.g. \"2026 Sept\"): it brings in each day's figure as stock history, and its latest day as the stock.": "Vous pouvez aussi importer l'onglet récapitulatif mensuel (par ex. « 2026 Sept ») : il ajoute le chiffre de chaque jour à l'historique du stock, et celui du dernier jour devient le stock.",
  "You can generate a share link or send this by WhatsApp once it's created — open it from the list and click Preview.": "Vous pourrez générer un lien de partage ou l'envoyer par WhatsApp une fois créé — ouvrez-le depuis la liste et cliquez sur Aperçu.",
  "You can join from 15 minutes before it starts. This page will let you in then.": "Vous pourrez rejoindre 15 minutes avant le début. Cette page vous laissera entrer à ce moment-là.",
  "You can join from 15 minutes before.": "Vous pourrez rejoindre 15 minutes avant.",
  "You can see the sheet; people who manage the stock fill it in.": "Vous pouvez consulter la fiche ; les personnes qui gèrent le stock la remplissent.",
  "You can see these settings but your role can't change them. Ask someone with Company settings access.": "Vous pouvez voir ces paramètres mais votre rôle ne permet pas de les modifier. Demandez à une personne ayant accès aux paramètres de l'entreprise.",
  "You can send up to {n} files at a time.": "Vous pouvez envoyer jusqu'à {n} fichiers à la fois.",
  "You can't change your own roles.": "Vous ne pouvez pas changer vos propres rôles.",
  "You clocked in at {clockIn} on {date} but didn't clock out, so the system clocked you out automatically at {clockOut}, {hours} hours later.": "Vous avez pointé l'entrée à {clockIn} le {date} sans pointer la sortie ; le système a donc pointé votre sortie automatiquement à {clockOut}, {hours} heures plus tard.",
  "You confirmed you have read this": "Vous avez confirmé l'avoir lue",
  "You deleted this message": "Vous avez supprimé ce message",
  "You handled {n} of {of} customers. Great work!": "Vous avez traité {n} clients sur {of}. Bravo !",
  "You have {n} days of {type} left this year.": "Il vous reste {n} jours de {type} cette année.",
  "You have {n} days of leave left in {year}, after the {h} company holidays.": "Il vous reste {n} jours de congé en {year}, après les {h} jours fériés de l'entreprise.",
  "You have {n} work orders due today.": "Vous avez {n} ordres de travail dus aujourd’hui.",
  "You have 1 day of leave left in {year}, after the {h} company holidays.": "Il vous reste 1 jour de congé en {year}, après les {h} jours fériés de l'entreprise.",
  "You have changes that aren't saved yet.": "Vous avez des modifications non enregistrées.",
  "You have taken {n} day(s) more than your leave for {year}. They are owed to the company; HR will settle them with you.": "Vous avez pris {n} jour(s) de plus que vos congés de {year}. Ils sont dus à l'entreprise ; les RH les régleront avec vous.",
  "You haven't clocked in yet today. Your shift started at {time}.": "Vous n'avez pas encore pointé aujourd'hui. Votre poste a commencé à {time}.",
  "You keep {n} day(s) after this.": "Il vous restera {n} jour(s) après cela.",
  "You left the meeting.": "Vous avez quitté la réunion.",
  "you manage it": "vous le gérez",
  "You see {list}. HR decides who each manager can see.": "Vous voyez {list}. Les RH décident qui chaque responsable peut voir.",
  "You see everyone at {companies}. HR or an administrator decides which companies each person can see.": "Vous voyez tout le personnel de {companies}. Les RH ou un administrateur décident quelles entreprises chaque personne peut voir.",
  "You see only yourself here: nobody reports to you yet and HR has not given you any departments or people.": "Vous ne voyez que vous-même ici : personne ne dépend encore de vous et les RH ne vous ont attribué aucun département ni aucune personne.",
  "You still have {n} days of paid leave this year. Plan them before 31 December.": "Il vous reste {n} jours de congé payé cette année. Planifiez-les avant le 31 décembre.",
  "You went through all {n}.": "Vous les avez tous parcourus ({n}).",
